def version_of(files: dict[str, str]) -> str:
    """Hash of every file's name and full text, in name order."""
    h = hashlib.sha256()
    for name in sorted(files):
        h.update(name.encode())
        h.update(b"\0")
        h.update(files[name].encode())
        h.update(b"\0")
    return h.hexdigest()[:12]


def read_files(directory: Path = CRITERIA_DIR) -> dict[str, str]:
    return {f"{name}.md": (directory / f"{name}.md").read_text() for name in CRITERIA_FILES}


def load(directory: Path = CRITERIA_DIR) -> CriteriaSet:
    missing = [n for n in CRITERIA_FILES if not (directory / f"{n}.md").exists()]
    if missing:
        raise CriteriaError(f"missing criteria files: {', '.join(missing)}")
    labels = {n: parse_file(directory / f"{n}.md") for n in CRITERIA_FILES}
    return CriteriaSet(version=version_of(read_files(directory)), labels=labels)


def criteria_text(criteria: CriteriaSet, label: str) -> str:
    """A label's definition and rules as written; the text Jev receives for it."""
    c = criteria.labels[label]
    return "\n".join([c.definition, *(f"{r.id}: {r.text}" for r in c.rules)])
"""Read and write stage files: each is a JSON list of one contract, or a single object."""

import json
import re
from pathlib import Path
from typing import TypeVar

from pydantic import BaseModel, TypeAdapter

M = TypeVar("M", bound=BaseModel)


def read_list(path: Path, model: type[M]) -> list[M]:
    return TypeAdapter(list[model]).validate_json(path.read_text())  # type: ignore[valid-type]


def write_list(path: Path, items: list[M]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps([i.model_dump(mode="json") for i in items], indent=2, ensure_ascii=False) + "\n")


def read_one(path: Path, model: type[M]) -> M:
    return model.model_validate_json(path.read_text())


def write_one(path: Path, item: BaseModel) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(item.model_dump_json(indent=2) + "\n")


_WS = re.compile(r"\s+")


def normalize_ws(text: str) -> str:
    """Collapse every run of whitespace to one space; the form quotes are checked in."""
    return _WS.sub(" ", text).strip()


def quote_in(quote: str, body: str) -> bool:
    """True when `quote` appears verbatim in `body` after whitespace normalization."""
    q = normalize_ws(quote)
    return bool(q) and q in normalize_ws(body)
